const payload = $input.first().json;
const raw = payload.raw_data || payload;

// Validate required fields
const required = ['employee_id', 'email'];
for (const f of required) {
  if (!raw[f]) throw new Error(`Missing required HR field: ${f}`);
}

// Email validation
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailRegex.test(raw.email)) throw new Error(`Invalid email format: ${raw.email}`);

// Build user context
const offboarding_id = `OFFB-${Date.now()}-${raw.employee_id}`;

return [{
  json: {
    _offboarding_id: offboarding_id,
    _started_at: new Date().toISOString(),
    // User info
    employee_id: raw.employee_id,
    email: raw.email,
    username: raw.username || raw.email.split('@')[0],
    full_name: raw.full_name || raw.name || 'Unknown',
    manager_email: raw.manager_email || null,
    department: raw.department || 'Unknown',
    effective_date: raw.effective_date || new Date().toISOString(),
    termination_reason: raw.reason || 'Not specified',
    // Action tracking (populated as workflow progresses)
    actions_completed: [],
    actions_failed: [],
    // Confidence: HR webhooks are always high confidence (trusted source)
    confidence_score: 95,
    risk_level: 'Low'
  }
}];

