// Collect results from all parallel revocation actions
const context = $('Validate & Build Context').first().json;
const adResult = $('Disable Active Directory Account').first().json;
const oktaResult = $('Deactivate Okta Account').first().json;

const actions = [];
const failures = [];

// AD check
if (adResult.error || adResult.status >= 400) {
  failures.push({ action: 'disable_active_directory', error: adResult.error || adResult.message || 'HTTP ' + adResult.status });
} else {
  actions.push({ action: 'disable_active_directory', status: 'success', timestamp: new Date().toISOString() });
}

// Okta check
if (oktaResult.errorCode || oktaResult.status >= 400) {
  failures.push({ action: 'deactivate_okta', error: oktaResult.errorCode || 'HTTP ' + oktaResult.status });
} else {
  actions.push({ action: 'deactivate_okta', status: 'success', timestamp: new Date().toISOString() });
}

return [{
  json: {
    ...context,
    actions_completed: actions,
    actions_failed: failures,
    phase1_complete: failures.length === 0,
    phase1_errors: failures.length
  }
}];

// Build complete offboarding evidence record
const context = $('Collect Phase 1 Results').first().json;
const awsResult = $('Revoke AWS IAM Keys').first().json;
const azureResult = $('Revoke Azure Roles').first().json;
const vpnResult = $('Revoke VPN Certificate').first().json;

const allActions = [...(context.actions_completed || [])];
const allFailures = [...(context.actions_failed || [])];

// Check Phase 2 results
if (!awsResult.Error) allActions.push({ action: 'revoke_aws_iam', status: 'success', timestamp: new Date().toISOString() });
else allFailures.push({ action: 'revoke_aws_iam', error: awsResult.Error?.Message || 'Unknown error' });

if (azureResult.value !== undefined) allActions.push({ action: 'revoke_azure_roles', status: 'success', count: azureResult.value?.length || 0, timestamp: new Date().toISOString() });
else allFailures.push({ action: 'revoke_azure_roles', error: azureResult.error?.message || 'Unknown error' });

if (!vpnResult.error) allActions.push({ action: 'revoke_vpn_certificate', status: 'success', timestamp: new Date().toISOString() });
else allFailures.push({ action: 'revoke_vpn_certificate', error: vpnResult.error });

const completed_at = new Date().toISOString();
const start = new Date(context._started_at);
const end = new Date(completed_at);
const duration_seconds = Math.round((end - start) / 1000);

return [{
  json: {
    ...context,
    actions_completed: allActions,
    actions_failed: allFailures,
    total_actions: allActions.length + allFailures.length,
    actions_succeeded: allActions.length,
    actions_failed_count: allFailures.length,
    offboarding_complete: allFailures.length === 0,
    completed_at,
    duration_seconds,
    // SLA: target is < 900 seconds (15 minutes)
    sla_met: duration_seconds < 900
  }
}];

